use verus::prelude::*;

/// Returns the number of turns required to defeat an opponent
/// with given `health` and attack `strength`.
/// This is the ceiling of health/strength = (health + strength - 1) / strength.
/// Precondition: health >= 1, strength >= 1
#[verifier::spec]
fn exec_turns_to_defeat_spec(health: i64, strength: i64) -> i64 {
    requires(1 <= health && health <= 100);
    requires(1 <= strength && strength <= 100);
    ensures(result >= 1);
    ((health + strength - 1) / strength)
}

/// Implementation version, corresponds with spec above.
fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Convert to i64 to avoid overflow and for specs
    let h = health as i64;
    let s = strength as i64;
    ((h + s - 1) / s)
}

/// Determines if Takahashi wins given initial health and attack values.
/// Takahashi attacks first, and the player who reduces the opponent's
/// health to 0 or below first wins.
/// Returns "Yes" if Takahashi can defeat Aoki in no more turns than vice versa,
/// otherwise "No".
///
/// Preconditions: a,b,c,d ∈ [1, 100]
fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // Preconditions
    requires(1 <= a && a <= 100);
    requires(1 <= b && b <= 100);
    requires(1 <= c && c <= 100);
    requires(1 <= d && d <= 100);
    // Compute turns Takahashi needs to defeat Aoki
    let takahashi_turns = exec_turns_to_defeat(a, d); // Number of turns Aoki needs to defeat Takahashi
    let aoki_turns = exec_turns_to_defeat(c, b);      // Number of turns Takahashi needs to defeat Aoki

    decreases(0);

    // Takahashi wins if he needs <= turns than Aoki does, since he attacks first
    if aoki_turns <= takahashi_turns {
        // Takahashi defeats Aoki first or simultaneously, so Takahashi wins
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

#[verifier::proof]
fn test_exec_turns_to_defeat_spec() {
    // Check some example proofs about spec function correctness
    assert(exec_turns_to_defeat_spec(10, 3) == 4);
    assert(exec_turns_to_defeat_spec(1, 1) == 1);
    assert(exec_turns_to_defeat_spec(100, 10) == 10);
}

#[verifier::proof]
fn test_solve_logic() {
    // Takahashi health=10, attack=5, Aoki health=10, attack=5
    // Both take 2 turns to defeat the other, Takahashi attacks first,
    // so result should be "Yes"
    let result1 = solve(10, 5, 10, 5);
    assert(result1 == "Yes");

    // Takahashi health=1, attack=1, Aoki health=100, attack=100
    // Takahashi needs 100 turns, Aoki needs 1 turn, so result "No"
    let result2 = solve(1, 1, 100, 100);
    assert(result2 == "No");
}